-- pintopets_parasite_treatments: tenant-scoped rows behind /parasite-treatments (generated by `opsapi make:resource`).
-- Runs once, inside a transaction. Never edit it after it has been applied —
-- add a new migration file instead.
return function(schema, db)
    db.query([[
        CREATE TABLE IF NOT EXISTS pintopets_parasite_treatments (
            id BIGSERIAL PRIMARY KEY,
            uuid UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
            namespace_id INTEGER NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
            pet_uuid UUID NOT NULL REFERENCES pintopets_pets(uuid) ON DELETE CASCADE,
            created_by_user_uuid UUID NOT NULL,
            kind VARCHAR(255) NOT NULL,
            product VARCHAR(255) NOT NULL,
            given_on DATE NOT NULL,
            next_due_on DATE,
            notes TEXT,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
            CONSTRAINT pintopets_parasite_treatments_kind_check CHECK (kind IN ('flea', 'worm', 'tick', 'flea_and_tick', 'lungworm', 'mite', 'other'))
        )
    ]])
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_parasite_treatments_namespace ON pintopets_parasite_treatments (namespace_id, id DESC)")
    db.query("CREATE INDEX IF NOT EXISTS idx_pintopets_parasite_treatments_pet ON pintopets_parasite_treatments (namespace_id, pet_uuid)")
end
